/* ---------- validation + all blog pages ---------- */
export function validateBlog(blog) {
  const errs = [];
  if (blog == null) return errs;
  if (typeof blog !== 'object' || !Array.isArray(blog.posts)) return ['部落格資料格式錯誤（需要 posts 清單）'];
  const seen = new Set();
  blog.posts.forEach((raw, i) => {
    const p = raw && typeof raw === 'object' ? mergeLoc(raw) : raw;
    const nm = '部落格文章「' + ((p && zhOr(p.title)) || i + 1) + '」';
    if (!p || typeof p !== 'object') { errs.push('部落格文章 ' + (i + 1) + ' 格式錯誤'); return; }
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(p.slug || '')) errs.push(nm + '的網址代稱只能用小寫英文、數字和連字號');
    if (seen.has(p.slug)) errs.push(nm + '的網址代稱重複'); seen.add(p.slug);
    if (!zhOr(p.title)) errs.push(nm + '需要標題');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(p.date || '')) errs.push(nm + '的日期格式須為 YYYY-MM-DD');
    if (p.updated != null && !/^\d{4}-\d{2}-\d{2}$/.test(p.updated)) errs.push(nm + '的更新日期格式須為 YYYY-MM-DD');
    const cs = Array.isArray(p.categories) ? p.categories : [p.categories];
    if (!cs.length || cs.some(c => !CAT[c])) errs.push(nm + '的分類必須是：' + BLOG_CATEGORIES.map(c => c.id).join(', '));
    if (!zhOr(p.body)) errs.push(nm + '需要內文');
    const html = [loc(p.body, 'zh-Hant'), loc(p.body, 'zh-Hans'), loc(p.body, 'en')].join('');
    if (/mmbiz\.(qpic|qlogo)\.cn|qpic\.cn/i.test(html + (p.cover || ''))) errs.push(nm + '含微信圖片網址（會被防盜鏈擋），請下載到 assets/blog/ 再引用');
    if (/<script/i.test(html)) errs.push(nm + '的內文不能含 <script>');
    if (p.faq != null && (!Array.isArray(p.faq) || p.faq.some(f => !f || !zhOr(f.q) || !zhOr(f.a)))) errs.push(nm + '的 FAQ 每項需要 q 與 a');
    if (p.keywords != null && (!Array.isArray(p.keywords) || p.keywords.some(k => typeof k !== 'string'))) errs.push(nm + '的關鍵字必須是文字清單');
  });
  return errs;
}
export function renderBlog(all, opts) {
  const out = { 'blog/index.html': renderBlogIndex(all.site, all.blog, opts) };
  for (const p of blogPostsAll(all.blog)) out[postPath(p.slug)] = renderBlogPost(all.site, all.blog, p, opts);
  return out;
}
export { siteJsonLd };
